"""Independently recompute evidence checks without making model calls."""
import json,re,hashlib,statistics,collections,csv,sys
from pathlib import Path
run=Path(sys.argv[1]);root=Path('tests/fixtures/contract-review-multilingual-20261017')
manifest=json.loads((root/'manifest.json').read_text());cases={c['caseId']:c for c in manifest['cases']}
records=json.loads((run/'summary.json').read_text());checks=[];semantic=[]
