for r in records:
 c=cases[r['caseId']];d=run/r['id'];request=json.loads((d/'request.json').read_text());execution=json.loads((d/'execution.json').read_text())['data'];output=json.loads((d/'output.json').read_text());usage=json.loads((d/'usage.json').read_text())['data'];artifact=json.loads((d/'artifact-check.json').read_text());events=json.loads((d/'events.json').read_text());clauses=output['clauses']
 body=norm('\n'.join((x.get('title','')+'\n'+x.get('originalContent','')) for x in clauses));markers=[m for m in c['contentMarkers'] if m not in body]
 f=next(f for f in c['files'] if f['path']==r['file']);rows=[x for x in usage if x.get('purpose')=='llm_operation']
 integrity={'fixture_digest':hashlib.sha256((root/r['file']).read_bytes()).hexdigest()==f['sha256'],'task_mode':request['config']['mode']=='task','requested_35b':request['modelId']=='d13e0d30-87b9-4e87-b96a-d8b1b3cf78af','identity':execution['id']==r['executionId'],'done':events[-1]['event']['type']=='done','actual_model_35b':bool(rows) and all(x['modelId']=='qwen36-35b-a3b' for x in rows),'artifact_digest':hashlib.sha256((d/'artifact.html').read_bytes()).hexdigest()==artifact['sha256']}
 # Identity/default provenance checks are evaluated separately from model-call provenance.
 notices=execution.get('inputJson',{}).get('__promptDebug',{}).get('notes',[])
 for item in c['expectedObservations']:
  if item['observation'].startswith(('risk_','bilingual_conflict')):
   matched=[x for x in clauses if item['marker'] in norm(x.get('title','')+' '+x.get('originalContent',''))]
   semantic.append({'case':r['id'],'marker':item['marker'],'expectedTopic':item['observation'],'sourcePresent':bool(matched),'riskLevels':[x['riskLevel'] for x in matched],'hasRiskSignal':any(x['riskLevel']!='PASS' for x in matched),'texts':[{'summary':x.get('riskSummary'),'advice':x.get('legalAdvice'),'source':x.get('originalContent')} for x in matched],'verdict':'NOT_FULL_LEGAL_ACCURACY_EVAL'})
 checks.append({'id':r['id'],'caseId':r['caseId'],'business':r['business'],'language':r['language'],'format':r['format'],'executionId':r['executionId'],'status':r['status'],'executionStatus':execution['status'],'integrity':integrity,'missingMarkers':markers,'markerCoverage':8-len(markers),'totalClauses':len(clauses),'semanticReviewed':output['metrics']['llmReviewedCount'],'degraded':output['metrics']['isDegraded'],'warnings':output['metrics']['warnings'],'contractType':output['contractType'],'expectedType':expected_types.get(r['business']),'typeMatches':output['contractType']==expected_types[r['business']] if r['business'] in expected_types else None,'position':output['myPosition'],'positionSource':output.get('positionSource'),'recognizerModels':sorted(set(x.get('modelId','unknown') for x in execution.get('inputJson',{}).get('__promptDebug',{}).get('llmCalls',[]) if x.get('stage')=='recognizer')),'recognizerErrors':[n for n in notices if 'recognizer' in n and '失败' in n],'chatMs':r['chatMs'],'uploadMs':r['uploadMs'],'wallMs':r['wallMs'],'calls':len(rows),'inputTokens':sum(x['inputTokens'] for x in rows),'outputTokens':sum(x['outputTokens'] for x in rows),'failureNames':[x['name'] for x in r.get('failures',[])]})
