with (run/'results.csv').open('w',encoding='utf-8-sig',newline='') as f:
 fields=['id','business','language','format','executionId','status','executionStatus','markerCoverage','totalClauses','contractType','position','positionSource','degraded','chatMs','calls','inputTokens','outputTokens'];w=csv.DictWriter(f,fieldnames=fields,extrasaction='ignore');w.writeheader();w.writerows(sorted(checks,key=lambda x:x['id']))
print(json.dumps({k:v for k,v in summary.items() if k!='results'},ensure_ascii=False,indent=2))
